import React, { useEffect, useState } from 'react';
import { getFiles } from '../services/api'; // Fetch real data
import { Bar, Line } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, BarElement, Title, Tooltip, Legend } from 'chart.js';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, BarElement, Title, Tooltip, Legend);

const Performance = () => {
  const [files, setFiles] = useState([]);

  useEffect(() => {
    const loadData = async () => {
        try {
            const res = await getFiles();
            setFiles(res.data);
        } catch (e) { console.error(e); }
    };
    loadData();
  }, []);

  // Process Real Data for Charts
  const hybridFiles = files.filter(f => f.mode === 'hybrid');
  const baselineFiles = files.filter(f => f.mode !== 'hybrid');

  const latencyChartData = {
    labels: files.map(f => f.filename.substring(0, 10)), // Truncate names
    datasets: [
      {
        label: 'Encryption Latency (ms)',
        data: files.map(f => f.metrics.aes),
        borderColor: '#00ff9d',
        backgroundColor: 'rgba(0, 255, 157, 0.2)',
        tension: 0.4
      },
      {
        label: 'Total Time (ms)',
        data: files.map(f => f.metrics.total),
        borderColor: '#00f3ff',
        backgroundColor: 'rgba(0, 243, 255, 0.2)',
        tension: 0.4
      }
    ]
  };

  return (
    <div className="p-8 space-y-8 h-full overflow-y-auto">
       <h2 className="text-2xl font-bold text-white mb-2">System Telemetry</h2>
       
       <div className="grid grid-cols-2 gap-8">
           {/* Chart 1: Real Latency */}
           <div className="bg-scifi-panel border border-scifi-border p-6 rounded-xl">
               <h3 className="text-gray-400 text-sm mb-4">Live Encryption Latency (All Files)</h3>
               {files.length > 0 ? (
                   <Line options={{ responsive: true, scales: { y: { grid: { color: '#222' } } } }} data={latencyChartData} />
               ) : (
                   <p className="text-gray-600 text-sm italic">No data available. Upload files to generate metrics.</p>
               )}
           </div>

           {/* Metrics Cards */}
           <div className="grid grid-cols-2 gap-4">
               <MetricCard title="Files Secured" value={files.length} sub="Total Vault Items" />
               <MetricCard title="Avg. PQC Overhead" value={
                   files.length > 0 ? (files.reduce((acc, f) => acc + f.metrics.pqc, 0) / files.length).toFixed(3) + " ms" : "0.00 ms"
               } sub="Kyber-512 Encap" />
               <MetricCard title="Storage Used" value={
                   (files.reduce((acc, f) => acc + f.size, 0) / 1024).toFixed(2) + " KB"
               } sub="Encrypted Blobs" />
               <MetricCard title="Integrity Check" value="SHA-256" sub="HMAC/GCM Tagging" />
           </div>
       </div>
    </div>
  );
};

const MetricCard = ({ title, value, sub }) => (
    <div className="bg-black/40 border border-gray-800 p-6 rounded-lg flex flex-col justify-center items-center text-center">
        <p className="text-gray-500 text-xs uppercase mb-2 tracking-widest">{title}</p>
        <p className="text-3xl font-bold text-neon-green font-mono">{value}</p>
        <p className="text-gray-600 text-[10px] mt-1">{sub}</p>
    </div>
);

export default Performance;
